// moveEntity/animateRig/updatePlayer/updateEffects/updateFloaters moved verbatim out of
// main.js (M6). Free identifiers: T (three, module import), resolveMove/distance (./combat.js,
// moveEntity/updatePlayer/updateEffects), abilitiesFor/classFor (./classes.js, updatePlayer),
// predictDodge (./multiplayer-motion.js, updatePlayer). findPath/hasLineOfSight (./combat.js)
// and animateHeroAttack (./combat-effects.js) are re-imported the same way but through a
// `deps` escape hatch defaulting to that same import -- the only deviation from verbatim --
// because the migrated mouse-targeting test needs to stub them the way its old vm context
// did. ctx.player/ctx.networkDirection/ctx.moveTarget/ctx.environment/ctx.state/ctx.keys/
// ctx.joystickValue/ctx.dodgeTime/ctx.angle/ctx.dodgeAngle/ctx.movePath/ctx.lockedEnemy/
// ctx.life/ctx.pendingRegionInteraction/ctx.lastMove/ctx.lastSnapshot/ctx.network/
// ctx.aimActive/ctx.mouseTargeting/ctx.targetWorld/ctx.attackHeld/ctx.heroRig/ctx.lastStep/
// ctx.audio/ctx.selection/ctx.playerLight/ctx.effects/ctx.classEffects/ctx.combatEffects/
// ctx.enemies/ctx.networkProjectiles/ctx.spellLight/ctx.floaters/ctx.camera (already-declared
// ctx data fields). ctx.worldBounds (game-context.js). ctx.removeObject (already wired by
// M3's createEffects). ctx.attacksFromHere (already wired by M5's bindInput). ctx.perform/
// ctx.footstepCue (main.js functions this task adds to ctx, since updatePlayer reaches them
// across the module boundary). Math/innerWidth/innerHeight (globals). updatePlayer calls
// moveEntity and animateRig directly -- both stay in this closure, same as groundPing calling
// ringEffect directly in effects-factory.js.
import * as T from './vendor/three.core.js';
import {resolveMove,distance,findPath as findPathImport,hasLineOfSight as hasLineOfSightImport} from './combat.js';
import {abilitiesFor,classFor} from './classes.js';
import {predictDodge} from './multiplayer-motion.js';
import {animateHeroAttack as animateHeroAttackImport} from './combat-effects.js';
export function createPlayerMotion(ctx,deps={}){
 const {hasLineOfSight=hasLineOfSightImport,findPath=findPathImport,animateHeroAttack=animateHeroAttackImport}=deps;
 function moveEntity(model,dx,dz,radius=.42){if(model===ctx.player){const length=Math.hypot(dx,dz);if(length>0)ctx.networkDirection={x:dx/length,z:dz/length,...(ctx.moveTarget?{stopAt:{x:ctx.moveTarget.x,z:ctx.moveTarget.z}}:{})};}const p=resolveMove(model.position,dx,dz,ctx.environment.obstacles,radius,ctx.worldBounds());const moved=Math.hypot(p.x-model.position.x,p.z-model.position.z);model.position.x=p.x;model.position.z=p.z;return moved;}
 function animateRig(rig,t,moving,windup=0,type='warden'){const speed=type==='hound'?13:9;for(let i=0;i<rig.legs.length;i++){const leg=rig.legs[i];const sign=leg.name.includes('L')?-1:1;const back=leg.name.includes('Back')?-1:1;leg.rotation.x=moving?Math.sin(t*speed)*.55*sign*back:Math.sin(t*1.7)*.025;}if(rig.body){rig.body.rotation.z=Math.sin(t*2.1)*.016;rig.body.rotation.x=windup*-.22;rig.body.position.y=(rig.baseY??1.18)+(moving?Math.abs(Math.sin(t*speed))*.035:0);}for(let i=0;i<rig.arms.length;i++){rig.arms[i].rotation.x=windup*-1.3+(moving?Math.sin(t*speed)*(i%2?-.2:.2):Math.sin(t*1.8+i)*.04);}}
 function updatePlayer(dt,t){ctx.networkDirection={x:0,z:0};if(ctx.state.ended){ctx.player.rotation.z=T.MathUtils.lerp(ctx.player.rotation.z,-1.5,dt*3);return;}let moving=false;const horiz=(ctx.keys.has('d')||ctx.keys.has('arrowright')?1:0)-(ctx.keys.has('a')||ctx.keys.has('arrowleft')?1:0)+ctx.joystickValue.x,vert=(ctx.keys.has('s')||ctx.keys.has('arrowdown')?1:0)-(ctx.keys.has('w')||ctx.keys.has('arrowup')?1:0)+ctx.joystickValue.y;let dx=.837*horiz+.547*vert,dz=-.547*horiz+.837*vert;
  if(ctx.dodgeTime>0){ctx.angle=ctx.dodgeAngle;const next=predictDodge(ctx.player.position,ctx.angle,ctx.dodgeTime,dt,ctx.environment.obstacles,ctx.worldBounds());ctx.player.position.x=next.x;ctx.player.position.z=next.z;ctx.dodgeTime=next.remaining;moving=true;ctx.player.position.y=ctx.state.classId==='oathkeeper'?Math.sin(Math.min(1,ctx.dodgeTime/.12)*Math.PI*.5)*.2:Math.sin(ctx.dodgeTime/.27*Math.PI)*.24;}
  else{ctx.player.position.y=0;if(Math.hypot(dx,dz)>.05){ctx.moveTarget=null;ctx.movePath=[];ctx.lockedEnemy=null;ctx.life.pending=null;ctx.pendingRegionInteraction=null;}else if(ctx.lockedEnemy&&!ctx.lockedEnemy.dead&&ctx.attackHeld){const p=ctx.lockedEnemy.model.position;ctx.angle=Math.atan2(p.x-ctx.player.position.x,p.z-ctx.player.position.z);if(!ctx.attacksFromHere()&&(distance(ctx.player.position,p)>abilitiesFor(ctx.state).attack.range||!hasLineOfSight(ctx.player.position,p,ctx.environment.obstacles,.42))){let seek=p;if(!hasLineOfSight(ctx.player.position,p,ctx.environment.obstacles,.42)){if(!ctx.movePath.length)ctx.movePath=findPath(ctx.player.position,p,ctx.environment.obstacles,ctx.worldBounds());while(ctx.movePath.length&&distance(ctx.player.position,ctx.movePath[0])<.3)ctx.movePath.shift();if(ctx.movePath.length)seek=ctx.movePath[0];}dx=seek.x-ctx.player.position.x;dz=seek.z-ctx.player.position.z;}else ctx.perform('attack');}else if(ctx.moveTarget){dx=ctx.moveTarget.x-ctx.player.position.x;dz=ctx.moveTarget.z-ctx.player.position.z;if(Math.hypot(dx,dz)<.1){const next=ctx.movePath.shift();ctx.moveTarget=next?new T.Vector3(next.x,0,next.z):null;dx=dz=0;}}if(Math.hypot(dx,dz)>.05){const length=Math.hypot(dx,dz);dx/=length;dz/=length;ctx.lastMove.set(dx,0,dz);const speed=ctx.lastSnapshot?.players.find(p=>p.id===ctx.network.id)?.speed??classFor(ctx.state).speed,travel=ctx.moveTarget?Math.min(length,speed*dt):speed*dt;moving=moveEntity(ctx.player,dx*travel,dz*travel)>.001;if(!ctx.attackHeld)ctx.angle=Math.atan2(dx,dz);}else if(ctx.aimActive&&!(ctx.attackHeld&&ctx.lockedEnemy)){ctx.getPointerWorld();const aim=ctx.mouseTargeting?.selected?.model.position||ctx.targetWorld;ctx.angle=Math.atan2(aim.x-ctx.player.position.x,aim.z-ctx.player.position.z);}if(ctx.attackHeld&&!ctx.lockedEnemy)ctx.perform('attack');}
  ctx.network.input={...ctx.networkDirection,angle:ctx.angle};ctx.player.rotation.y=ctx.angle;animateRig(ctx.heroRig,t,moving);animateHeroAttack(ctx.heroRig,dt);if(moving&&t-ctx.lastStep>.29&&!(ctx.state.classId==='oathkeeper'&&(ctx.state.valkyrieTime>0||ctx.dodgeTime>0))){ctx.audio.play(ctx.footstepCue(),.48);ctx.lastStep=t;}ctx.selection.position.set(ctx.player.position.x,.1,ctx.player.position.z);ctx.selection.material.opacity=ctx.dodgeTime>0?.2:.55;ctx.playerLight.position.copy(ctx.player.position).add(new T.Vector3(0,2.7,0));}
 function updateEffects(dt){
  for(let i=ctx.effects.length-1;i>=0;i--){const e=ctx.effects[i];e.time+=dt;const p=e.time/e.life;if(p>=1){ctx.removeObject(e.mesh);ctx.effects.splice(i,1);continue;}e.mesh.material.opacity=(1-p)*.85;if(e.type==='ring'){const r=T.MathUtils.lerp(e.from,e.to,1-(1-p)*(1-p));e.mesh.scale.setScalar(r);}if(e.type==='slash'){e.mesh.rotation.z=e.angle-.35+p*.9;e.mesh.scale.setScalar(.8+p*.3);}if(e.type==='sparks'){const data=e.mesh.geometry.attributes.position.array;for(let j=0;j<data.length;j+=6){const v=j/2;for(let axis=0;axis<3;axis++){data[j+axis]+=e.velocity[v+axis]*dt;data[j+3+axis]=data[j+axis]-e.velocity[v+axis]*.022;}e.velocity[v+1]-=dt*9;}e.mesh.geometry.attributes.position.needsUpdate=true;}if(e.type==='particles'){const data=e.mesh.geometry.attributes.position.array;for(let j=0;j<data.length;j+=3){data[j]+=e.velocity[j]*dt;data[j+1]+=e.velocity[j+1]*dt;data[j+2]+=e.velocity[j+2]*dt;e.velocity[j+1]-=dt*6;}e.mesh.geometry.attributes.position.needsUpdate=true;}}
  ctx.classEffects.update(dt);ctx.combatEffects.update(dt,[...ctx.classEffects.lightSources(),...ctx.enemies.filter(e=>e.visuals.light.intensity&&distance(e.model.position,ctx.player.position)<20).map(e=>e.visuals.light),...[...ctx.networkProjectiles.values()].filter(b=>b.visual?.light?.position).map(b=>b.visual.light)]);ctx.spellLight.intensity=Math.max(0,ctx.spellLight.intensity-dt*160);}
 function updateFloaters(dt){for(let i=ctx.floaters.length-1;i>=0;i--){const f=ctx.floaters[i];f.time+=dt;if(f.time>=f.life){f.element.remove();ctx.floaters.splice(i,1);continue;}const projected=f.pos.clone().project(ctx.camera);const x=(projected.x*.5+.5)*innerWidth,y=(-projected.y*.5+.5)*innerHeight;f.element.style.transform=`translate(${x+f.offset}px,${y-f.time*55}px) translate(-50%,-50%)`;f.element.style.opacity=String(Math.min(1,(f.life-f.time)*3));}}
 return {moveEntity,animateRig,updatePlayer,updateEffects,updateFloaters};
}
